const FX=(()=>{
 let audio=null,serial=0,milestone=0;let power='max';try{power=localStorage.getItem('chem-fx-power')||'max';}catch{}if(!['low','normal','max','ultra'].includes(power))power='max';
 const powerInput=document.getElementById('fx-power');powerInput.value=power;powerInput.onchange=()=>{clear();power=powerInput.value;try{localStorage.setItem('chem-fx-power',power);}catch{}applyPower();if(power==='ultra'){toast('超派手モード ON！','正解も、コンボも、クリアも大爆発！');flare();play('win');}};const nodes=new Set();
 function applyPower(){document.documentElement.classList.toggle('ultra-fx',power==='ultra');}
 applyPower();
 const systemReduced=typeof matchMedia==='function'?matchMedia('(prefers-reduced-motion: reduce)'):null;
 function stored(key,fallback){try{const v=localStorage.getItem('chem-fx-'+key);return v===null?fallback:v==='true';}catch{return fallback;}}
 const settings={motion:stored('motion',true),sound:stored('sound',false),vibration:stored('vibration',false)};
 const motion=()=>settings.motion&&!systemReduced?.matches;
 function sync(){document.documentElement.classList.toggle('reduce-fx',!motion());}
 for(const key of Object.keys(settings)){const input=document.getElementById('fx-'+key);input.checked=settings[key];input.onchange=()=>{settings[key]=input.checked;try{localStorage.setItem('chem-fx-'+key,String(input.checked));}catch{}sync();if(key==='sound'&&input.checked)play('match',1);if(key==='motion'&&!motion())clear();};}
 systemReduced?.addEventListener('change',sync);sync();
 function unlock(){if(!settings.sound)return;try{const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;if(!audio)audio=new Context();if(audio.state==='suspended')audio.resume().catch(()=>{});}catch{}}
 function play(kind,combo=1){if(!settings.sound)return;unlock();if(!audio||audio.state!=='running')return;const notes=kind==='win'?[523,659,784,1047,1319]:kind==='match'?[523,659,784*Math.pow(1.06,Math.min(combo-1,6))]:kind==='miss'?[220]:kind==='start'?[392,523]:[440];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain(),at=audio.currentTime+i*.075;o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(.055,at+.009);g.gain.exponentialRampToValueAtTime(.001,at+.16);o.connect(g);g.connect(audio.destination);o.start(at);o.stop(at+.19);o.onended=()=>{o.disconnect();g.disconnect();};});}
 function vibrate(kind){if(settings.vibration&&typeof navigator!=='undefined'&&navigator.vibrate)navigator.vibrate(kind==='win'?[40,60,40,60,80]:kind==='match'?25:8);}
 function transient(node,parent,duration){if(node.className.includes('fx-particle')){const particles=[...nodes].filter(n=>n.className.includes('fx-particle'));if(particles.length>=260){particles[0].remove();nodes.delete(particles[0]);}}parent.appendChild(node);nodes.add(node);setTimeout(()=>{node.remove();nodes.delete(node);},duration);}
 function particles(x,y,win=false){if(!motion())return;const colors=['#8052ff','#ffb829','#15846e','#ec62b5','#7096ff'];for(let i=0;i<(win?(power==='ultra'?160:power==='max'?120:power==='normal'?75:30):(power==='ultra'?44:power==='max'?30:power==='normal'?18:8));i++){const p=document.createElement('span');p.className='fx-particle '+(win?'confetti':'spark')+(power==='ultra'?' ultra-particle':'');if(power==='ultra'&&i%4===0){p.className+=' star-particle';}p.style.left=(win?Math.random()*100+'vw':x+'px');p.style.top=(win?'-18px':y+'px');p.style.background=colors[i%colors.length];p.style.setProperty('--dx',(Math.random()-.5)*(win?250:180)+'px');p.style.setProperty('--dy',(-35-Math.random()*100)+'px');if(power==='ultra'&&!win){const angle=Math.random()*Math.PI*2,radius=90+Math.random()*100;p.style.setProperty('--dx',Math.cos(angle)*radius+'px');p.style.setProperty('--dy',Math.sin(angle)*radius+'px');}p.style.setProperty('--spin',(Math.random()*600-300)+'deg');p.style.setProperty('--delay',win?Math.random()*.5+'s':'0s');transient(p,document.body,win?3000:850);}}
 function toast(title,subtitle=''){if(power==='low')return;for(const n of [...nodes])if(n.className.includes('reward-toast')){n.remove();nodes.delete(n);}const n=document.createElement('div');n.className='reward-toast'+(power==='ultra'?' ultra-toast':'');n.setAttribute('aria-hidden','true');const star=document.createElement('span');star.className='reward-star';star.textContent='✦';const h=document.createElement('strong');h.textContent=title;const detail=document.createElement('small');detail.textContent=subtitle;n.appendChild(star);n.appendChild(h);n.appendChild(detail);transient(n,document.body,2100);}
 function shockwave(x,y){if(power!=='ultra'||!motion())return;for(let i=0;i<3;i++){const r=document.createElement('span');r.className='ultra-ring';r.style.left=x+'px';r.style.top=y+'px';r.style.setProperty('--ring-delay',i*65+'ms');transient(r,document.body,1000);}}
 function flare(){if(power!=='ultra'||!motion())return;for(const n of [...nodes])if(n.className==='ultra-halo'){n.remove();nodes.delete(n);}const halo=document.createElement('div');halo.className='ultra-halo';transient(halo,document.body,850);}
 function fireworks(){if(power!=='ultra'||!motion())return;const w=typeof window==='undefined'?400:window.innerWidth,h=typeof window==='undefined'?600:window.innerHeight;for(const [x,y]of [[.2,.25],[.8,.25],[.5,.45]]){particles(w*x,h*y);shockwave(w*x,h*y);}flare();}
 function record(title){play('win');vibrate('win');toast(title,'記憶が、新しい記録になった。');particles(0,0,true);fireworks();}
 function countUp(){if(!motion()||typeof requestAnimationFrame!=='function')return;const target=document.querySelector('.final-score');if(!target)return;const number=[...target.childNodes].find(n=>n.nodeType===3);if(!number)return;const total=Number(number.textContent.replaceAll(',',''));if(!Number.isFinite(total))return;const token=serial,begin=performance.now();function frame(now){if(token!==serial||!target.isConnected)return;const progress=Math.min(1,(now-begin)/900);number.textContent=Math.round(total*(1-Math.pow(1-progress,3))).toLocaleString();if(progress<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);}
 function match(indices,combo,points){Shizuku.react('match',combo);play('match',combo);vibrate('match');const wraps=cardWraps;for(const i of indices){const card=getCardWrap(i)?.querySelector('.card');if(!card)continue;card.classList.remove('match-pop');void card.offsetWidth;card.classList.add('match-pop');const box=card.getBoundingClientRect();particles(box.left+box.width/2,box.top+box.height/2);shockwave(box.left+box.width/2,box.top+box.height/2);const p=document.createElement('span');p.className='points-float'+(power==='ultra'?' ultra-points':'');p.textContent='+'+points;transient(p,wraps[i],1000);}
 const banner=document.getElementById('comboBanner');banner.textContent=combo>=2?`${combo}連続正解！ ${combo>=5?'絶好調 ✦':'コンボ ✦'}`:'ナイスペア！ ✦';banner.classList.remove('banner-pop');void banner.offsetWidth;banner.classList.add('banner-pop');const found=[...wraps].filter(w=>w.querySelector('.card')?.classList.contains('matched')).length/2;const progress=Math.floor(found/(wraps.length/2)*4);if(progress>milestone&&progress<4){milestone=progress;toast(progress===1?'25% COMPLETE':progress===2?'HALFWAY！':'あと少し！',`${found}ペアを発見！`);}else if(combo===3||combo===5||combo===8||combo>8&&combo%5===0){toast(combo>=5?'CHEMISTRY FEVER！':'TRIPLE MATCH！',`${combo}連続正解 · 記憶がつながってる！`);play('win');}else if(power==='ultra')toast(combo>=5?'超絶 FEVER！！':combo>=2?`${combo} COMBO！！`:'超正解！！',combo>=5?'記憶、覚醒！':`＋${points}点 · ナイスペア！`);else if(power==='max'&&combo===1)toast('NICE MATCH！','ひとつ覚えた！');if(power==='ultra'){flare();const board=document.getElementById('board');board.classList.remove('ultra-impact');void board.offsetWidth;board.classList.add('ultra-impact');}if(combo>=3){const board=document.getElementById('board');board.classList.remove('fever-pulse');void board.offsetWidth;board.classList.add('fever-pulse');}}
 function win(){Shizuku.react('win');play('win');vibrate('win');particles(0,0,true);const result=document.getElementById('result');result.classList.add('win-reveal');toast(power==='ultra'?'完全制覇！！':'ALL PAIRS COMPLETE！',power==='ultra'?'最高の記憶力、ここに降臨！':'全ペア正解、おつかれさま！');fireworks();countUp();}
 function clear(){serial++;milestone=0;document.getElementById('board').classList.remove('fever-pulse');document.getElementById('board').classList.remove('ultra-impact');for(const node of nodes)node.remove();nodes.clear();const b=document.getElementById('comboBanner');if(b){b.textContent='';b.classList.remove('banner-pop');}document.getElementById('result').classList.remove('win-reveal');}
 return {motion,play,unlock,vibrate,match,win,clear,record};
})();
